	rows, err := s.db.Query(
		`SELECT job_id, run_id, attempt, scheduled_for, started_at, finished_at, outcome, error
		   FROM run_attempts
		  WHERE job_id = ?
		    AND scheduled_for >= ? AND scheduled_for < ?
		  ORDER BY scheduled_for ASC, run_id ASC, attempt ASC`,
		jobID, from.UnixNano(), to.UnixNano(),
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var runs []*Run
	for rows.Next() {
		attempt, err := scanAttempt(rows)
		if err != nil {
			return nil, err
		}
		if len(runs) == 0 || runs[len(runs)-1].RunID != attempt.RunID {
			runs = append(runs, &Run{
				JobID:        attempt.JobID,
				RunID:        attempt.RunID,
				ScheduledFor: attempt.ScheduledFor,
			})
		}
		current := runs[len(runs)-1]
		current.Attempts = append(current.Attempts, attempt)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return runs, nil
}

// ExecutedAttempts returns every attempt whose scheduled instant falls in
// [from, to), ordered by scheduled instant, job and run identifiers and then
// attempt. History of soft-deleted jobs is included.
func (s *Store) ExecutedAttempts(from, to time.Time) ([]*Attempt, error) {
	rows, err := s.db.Query(
		`SELECT job_id, run_id, attempt, scheduled_for, started_at, finished_at, outcome, error
		   FROM run_attempts
		  WHERE scheduled_for >= ? AND scheduled_for < ?
		  ORDER BY scheduled_for ASC, job_id ASC, run_id ASC, attempt ASC`,
		from.UnixNano(), to.UnixNano(),
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var attempts []*Attempt
	for rows.Next() {
		attempt, err := scanAttempt(rows)
		if err != nil {
			return nil, err
		}
		attempts = append(attempts, attempt)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return attempts, nil
}

func scanRun(rows *sql.Rows) (*Run, error) {
	var run *Run
	for rows.Next() {
		attempt, err := scanAttempt(rows)
		if err != nil {
			return nil, err
		}
		if run == nil {
			run = &Run{
				JobID:        attempt.JobID,
				RunID:        attempt.RunID,
				ScheduledFor: attempt.ScheduledFor,
			}
		}
		run.Attempts = append(run.Attempts, attempt)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return run, nil
}

func scanAttempt(scanner rowScanner) (*Attempt, error) {
	attempt := &Attempt{}
	var scheduledNS, startedNS, finishedNS int64
	var failure sql.NullString
	if err := scanner.Scan(
		&attempt.JobID, &attempt.RunID, &attempt.Attempt,
		&scheduledNS, &startedNS, &finishedNS, &attempt.Outcome, &failure,
	); err != nil {
		return nil, err
	}
	attempt.ScheduledFor = time.Unix(0, scheduledNS).UTC()
	attempt.StartedAt = time.Unix(0, startedNS).UTC()
	attempt.FinishedAt = time.Unix(0, finishedNS).UTC()
	if failure.Valid {
		text := failure.String
		attempt.Error = &text
	}
	return attempt, nil
}

func nullableString(value *string) any {
	if value == nil {
		return nil
	}
	return *value
}

